// Rassemble les données publiques sur une CVE (aucune donnée perso).
const e = $input.first().json;
const cve = String(e.cve ?? '').toUpperCase();
if (!/^CVE-\d{4}-\d{4,7}$/.test(cve)) return [{ json: { erreur: 'Identifiant CVE invalide.' } }];

// Cache : on ne régénère pas un résumé de moins de 7 jours
const mem = $getWorkflowStaticData('global');
mem.resumes ??= {};
for (const [k, v] of Object.entries(mem.resumes)) if (Date.now() - v.date > 30 * 24 * 3600 * 1000) delete mem.resumes[k];
if (mem.resumes[cve] && Date.now() - mem.resumes[cve].date < 7 * 24 * 3600 * 1000) {
  return [{ json: { cve, cached: true } }];
}

const essayer = async (f) => { try { return await f(); } catch { return null; } };
// NVD : description, CVSS, CWE, références
const nvd = await essayer(() => this.helpers.httpRequest({ url: 'https://services.nvd.nist.gov/rest/json/cves/2.0', qs: { cveId: cve }, json: true, timeout: 20000 }));
const v = nvd?.vulnerabilities?.[0]?.cve;
const metrics = v?.metrics ?? {};
const mk = ['cvssMetricV40', 'cvssMetricV31', 'cvssMetricV30'].find(k => metrics[k]?.[0]);
const cvss = mk ? metrics[mk][0].cvssData : null;
const desc = v?.descriptions?.find(d => d.lang === 'en')?.value ?? '(description NVD indisponible)';
const cwe = [...new Set((v?.weaknesses ?? []).flatMap(w => (w.description ?? []).map(d => d.value)).filter(x => x && x !== 'NVP-Other'))];
const refs = (v?.references ?? []).map(r => r.url);

// EPSS : probabilité d'exploitation
const epssData = await essayer(() => this.helpers.httpRequest({ url: 'https://api.first.org/data/v1/epss', qs: { cve }, json: true, timeout: 15000 }));
const epss = epssData?.data?.[0];

// Dépôts publics nommés d'après la CVE (signal d'existence d'un PoC — jamais exécuté)
const gh = await essayer(() => this.helpers.httpRequest({ url: 'https://api.github.com/search/repositories', qs: { q: cve, per_page: 5, sort: 'stars' },
  headers: { 'User-Agent': 'assistant-veille', Accept: 'application/vnd.github+json' }, json: true, timeout: 15000 }));
const depots = (gh?.items ?? []).map(r => `${r.full_name} (${r.stargazers_count} étoiles)`);

const contexte = [
  `CVE : ${cve}`,
  `Description (NVD) : ${desc}`,
  cvss ? `CVSS : ${cvss.baseScore} (${cvss.baseSeverity}) — ${cvss.vectorString}` : 'CVSS : non disponible',
  cwe.length ? `Type de faiblesse (CWE) : ${cwe.join('; ')}` : '',
  epss ? `EPSS : ${(parseFloat(epss.epss) * 100).toFixed(1)}% de probabilité d'exploitation (percentile ${(parseFloat(epss.percentile) * 100).toFixed(0)})` : 'EPSS : non disponible',
  `Exploitation active confirmée (CISA KEV) : ${e.kev ? 'OUI' : 'non recensée'}`,
  `Dépôts publics repérés au nom de la CVE : ${depots.length ? depots.join(', ') : 'aucun'}`,
  refs.length ? `Références : ${refs.slice(0, 6).join(' | ')}` : '',
].filter(Boolean).join('\n');

return [{ json: { cve, cached: false, contexte,
  signaux: { cvss: cvss?.baseScore ?? null, epss: epss ? Math.round(parseFloat(epss.epss) * 100) : null, kev: !!e.kev, depots: depots.length } } }];

// Mémorise la fiche (cache 7 jours) et la renvoie à l'appelant
const prep = $('Collecter les données').first().json;
if (prep.erreur) return [{ json: prep }];
const r = $input.first().json;
if (r.error || !r.reponse) return [{ json: { erreur: 'Le cerveau n\'a pas pu rédiger : ' + String(r.error?.message ?? r.erreur ?? '').slice(0, 150) } }];
const mem = $getWorkflowStaticData('global');
mem.resumes ??= {};
mem.resumes[prep.cve] = { date: Date.now(), texte: r.reponse.trim(), signaux: prep.signaux };
return [{ json: { cve: prep.cve, ok: true } }];
